 'gm-7f':'paraSemb','gm-7d':'tunnel',
 'gc-1':'angCentre1','gc-2':'angCentre2','gc-5':'tangIsoc','gc-6':'tangAngle','gc-6b':'reuleaux','gc-6c':'trois3','gc-6d':['petalCarre','petale'],'gc-6e':'cerclesTang',
 'gm-1':'formeL','gm-2':'maison','gm-5':'carreDisque','gm-6':['uShape','anneauSecteur'],'gm-6b':'empilement','gm-6c':'ogive','gm-6d':'encoches','gm-6e':'segmentsDisque','gm-6f':'rosace','gm-6g':'hexDemi','gm-6h':'courroie','gm-6i':'lunules','gm-6j':'trapEnc','gm-6k':'facade','gm-6l':'triEnc',
