/* ===== Schémas des exercices originaux (gm-8a…8d, gc-7a…7d) ===== */
const gvPt=(cx,cy,r,deg)=>[cx+r*Math.cos(deg*Math.PI/180),cy-r*Math.sin(deg*Math.PI/180)];
GV.arbelosN=()=>({H:190,s:gvPath('M50 150 A120 120 0 0 1 290 150 A72 72 0 0 0 146 150 A48 48 0 0 0 50 150 Z',GVA)+gvD([50,150],[290,150])+gvDots([[50,150],[146,150],[290,150]])+gvT(50,165,'A','g-v')+gvT(146,165,'C','g-v')+gvT(290,165,'B','g-v')+gvT(170,60,'R','g-u')+gvT(98,128,'r1','g-t')+gvT(218,128,'r2','g-t')+gvT(170,100,'arbelos','g-t'),
  cap:'<b>Arbelos</b> : grand demi-disque de diamètre AB privé des deux petits (diamètres AC et CB). <b>A = π(R² − r1² − r2²) ÷ 2</b>, ce qui donne <b>π × r1 × r2</b> (car R = r1 + r2). Le contour = trois demi-cercles : <b>P = π(R + r1 + r2) = 2πR</b>. La base [AB] n\'est pas un bord.'});
GV.octoN=()=>{ const q=[[60,20],[220,20],[220,150],[60,150]],V=[[85,20],[195,20],[220,45],[220,125],[195,150],[85,150],[60,125],[60,45]]; return {H:180,s:gvPath('M60 20 L220 20 L220 150 L60 150 Z','fill:none','g-dash')+gvP(V,GVA)+gvC(140,85,65,'fill:var(--card-2);fill-opacity:1')+gvT(140,168,'côté du carré = 4k')+gvT(207,12,'k','g-t')+gvT(140,85,'disque Ø 4k','g-t'),
  cap:'<b>Octogone</b> = carré − 4 coins (triangles rectangles isocèles de côté k, aire k² ÷ 2). Côtés obliques : <b>k√2</b> (Pythagore) ; côtés droits : 4k − 2k = 2k. Le disque (diamètre = côté du carré) a pour rayon 2k, donc <b>πr² = 4πk²</b>. Aire colorée = <b>14k² − 4πk²</b>.'}; };
GV.rainureN=()=>({H:180,s:gvRect(40,20,260,130,GVG)+gvPath('M110 52 L230 52 A22 22 0 0 1 230 96 L110 96 A22 22 0 0 1 110 52 Z','fill:var(--card-2);fill-opacity:1')+gvD([110,52],[110,96])+gvD([230,52],[230,96])+gvT(170,74,'rectangle e × d','g-t')+gvT(88,74,'½','g-t')+gvT(252,74,'½','g-t')+gvC(95,125,14,'fill:var(--card-2);fill-opacity:1')+gvC(245,125,14,'fill:var(--card-2);fill-opacity:1')+gvT(170,125,'2 trous','g-t')+gvT(170,168,'longueur totale = e + d','g-t'),
  cap:'<b>Rainure oblongue</b> = un rectangle de longueur <b>e = longueur totale − d</b> et deux demi-disques de diamètre d (ensemble : un disque de rayon d÷2). Aire retirée = <b>e × d + π(d÷2)²</b>. Puis on retire les trous : <b>A = L × l − e × d − π(d÷2)² − n × π(Ø÷2)²</b>.'});
GV.cheminN=()=>({H:190,s:gvPath('M70 32 L250 32 A28 28 0 0 1 278 60 L278 130 A28 28 0 0 1 250 158 L70 158 A28 28 0 0 1 42 130 L42 60 A28 28 0 0 1 70 32 Z',GVG)+gvRect(70,60,180,70,'fill:var(--card-2);fill-opacity:1')+gvD([70,32],[70,60])+gvD([250,32],[250,60])+gvD([70,130],[70,158])+gvD([250,130],[250,158])+gvD([42,60],[70,60])+gvD([250,60],[278,60])+gvD([42,130],[70,130])+gvD([250,130],[278,130])+gvT(160,95,'jardin','g-t')+gvT(160,46,'rectangle L × w','g-t')+gvT(56,46,'¼','g-t')+gvT(264,46,'¼','g-t')+gvT(56,146,'¼','g-t')+gvT(264,146,'¼','g-t')+gvU(56,80,'w','middle'),
  cap:'<b>Chemin de largeur w</b> : 4 rectangles (2 de L × w, 2 de l × w) et 4 quarts de disque aux coins qui forment <b>un disque entier de rayon w</b>. <b>A = 2w(L + l) + πw²</b>. Bord extérieur : <b>2(L + l) + 2πw</b> (4 segments + un cercle).'});
GV.patronN=()=>{ const O=[95,105],s=72,A1=-18,A2=198,P1=gvPt(95,105,s,A1),P2=gvPt(95,105,s,A2); return {H:190,s:gvPath('M95 105 L'+P1[0].toFixed(1)+' '+P1[1].toFixed(1)+' A72 72 0 1 0 '+P2[0].toFixed(1)+' '+P2[1].toFixed(1)+' Z',GVA)+gvDots([O])+gvT(95,86,'θ','g-u')+gvT(150,125,'s','g-u')+gvPath('M270 24 L228 138 A42 12 0 0 0 312 138 Z','fill:none','g-l')+gvT(270,16,'sommet','g-t')+gvT(270,160,'cercle de base : r','g-t')+gvT(258,92,'s','g-u','end')+gvT(210,100,'⟶','g-t'),
  cap:'<b>Patron du cône</b> : l\'arc du secteur devient le cercle de base. <b>(θ ÷ 360) × 2πs = 2πr</b>, donc <b>r = s × θ ÷ 360</b>. Aire latérale = aire du secteur = <b>π × r × s</b>. Aire totale = π r s + π r² = <b>πr(s + r)</b>.'}; };
GV.inscritN=()=>{ const C=[70,140],A=[250,140],B=[70,40],a=180,b=100,c=Math.hypot(a,b),r=(a+b-c)/2,I=[70+r,140-r]; return {H:180,s:gvP([C,A,B],GVA)+gvC(I[0],I[1],r,'fill:var(--card-2);fill-opacity:1')+gvDots([I,[70+r,140],[70,140-r]])+g.right(C,A,B,10)+gvT(60,150,'C','g-v','end')+gvT(256,150,'A','g-v','start')+gvT(60,34,'B','g-v','end')+gvT(70+r/2,152,'r','g-u')+gvT(56,140-r/2,'r','g-u','end')+gvT(70+r+(a-r)/2,152,'CA − r','g-t')+gvT(150,60,'AB = (CA − r) + (CB − r)','g-t','start'),
  cap:'<b>Cercle inscrit</b> dans un triangle rectangle en C : le rayon et les deux tangentes issues de C forment un carré de côté r. Les tangentes issues d\'un même point sont égales : <b>AB = (CA − r) + (CB − r)</b>, donc <b>r = (CA + CB − AB) ÷ 2</b>. Aire colorée = CA × CB ÷ 2 − πr².'}; };
GV.hypoDiamN=()=>{ const O=[170,85],R=70,C=gvPt(170,85,70,122); return {H:180,s:gvC(170,85,70,GVA)+gvP([[100,85],[240,85],C],'fill:var(--card-2);fill-opacity:1')+g.right(C,[100,85],[240,85],10)+gvDots([O,[100,85],[240,85],C])+gvT(92,92,'A','g-v','end')+gvT(248,92,'B','g-v','start')+gvT(C[0]-8,C[1]-8,'C','g-v','end')+gvT(172,98,'O','g-v','start')+gvT(170,170,'AB = 2R','g-t')+gvT(122,52,'a','g-t','end')+gvT(222,60,'b','g-t','start'),
  cap:'<b>Triangle inscrit dont un côté est un diamètre</b> : l\'angle en C est droit. [AB] = 2R est l\'hypoténuse, donc <b>b = √((2R)² − a²)</b> (Pythagore). Partie colorée = disque − triangle = <b>πR² − a × b ÷ 2</b>.'}; };
GV.vide4=()=>({t:'Quatre disques (centres = sommets d\'un carré)',H:180,s:gvC(130,50,40,'fill:var(--accent);fill-opacity:.1')+gvC(210,50,40,'fill:var(--accent);fill-opacity:.1')+gvC(210,130,40,'fill:var(--accent);fill-opacity:.1')+gvC(130,130,40,'fill:var(--accent);fill-opacity:.1')+gvPath('M170 50 A40 40 0 0 0 210 90 A40 40 0 0 0 170 130 A40 40 0 0 0 130 90 A40 40 0 0 0 170 50 Z',GVG)+gvP([[130,50],[210,50],[210,130],[130,130]],'fill:none','g-dash')+gvDots([[130,50],[210,50],[210,130],[130,130]])+gvT(150,42,'r','g-u')+gvT(170,100,'2r','g-t'),
  cap:'Centres à distance 2r : carré de côté 2r. Chaque sommet contient un <b>quart de disque</b> (90°) : ensemble, un disque. <b>A = (2r)² − πr² = r²(4 − π)</b>. Contour : 4 arcs de 90° = <b>2πr</b>.'});
GV.vide3=()=>({t:'Trois disques (centres = sommets d\'un triangle équilatéral)',H:190,s:gvC(134,140,36,'fill:var(--accent);fill-opacity:.1')+gvC(206,140,36,'fill:var(--accent);fill-opacity:.1')+gvC(170,77.7,36,'fill:var(--accent);fill-opacity:.1')+gvPath('M170 140 A36 36 0 0 1 188 108.8 A36 36 0 0 1 152 108.8 A36 36 0 0 1 170 140 Z',GVG)+gvP([[134,140],[206,140],[170,77.7]],'fill:none','g-dash')+gvDots([[134,140],[206,140],[170,77.7]])+gvT(152,152,'r','g-u')+gvT(170,184,'2r','g-t'),
  cap:'Centres à distance 2r : triangle équilatéral de côté 2r, d\'aire <b>√3 r²</b>. Chaque sommet contient un <b>secteur de 60°</b> (1⁄6 de disque) : trois secteurs = demi-disque. <b>A = √3 r² − πr² ÷ 2</b>. Contour : 3 arcs de 60° = <b>πr</b>.'});
Object.assign(GVMAP,{'gm-8a':'arbelosN','gm-8b':'octoN','gm-8c':'rainureN','gm-8d':'cheminN','gc-7a':'patronN','gc-7b':'inscritN','gc-7c':'hypoDiamN','gc-7d':['vide4','vide3']});
